descriptor.templateCss:
.mv-root { height: 100%; }
.mv-card {
  height: 100%; box-sizing: border-box; padding: 4px 12px; border-radius: 12px; position: relative;
  display: flex; align-items: center; gap: 10px; overflow: hidden;
  background: #fff; border: 1px solid rgba(0, 0, 0, .08); box-shadow: 0 1px 4px rgba(0, 0, 0, .05);
  font-family: Roboto, sans-serif; color: rgba(0, 0, 0, .87);
}
.mv-card.clickable { cursor: pointer; transition: box-shadow .15s, border-color .15s; }
.mv-card.clickable:hover { border-color: var(--accent); box-shadow: 0 2px 8px rgba(0, 0, 0, .12); }
.mv-icon {
  flex: none; width: 28px; height: 28px; border-radius: 8px; display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--accent) 14%, #fff); color: var(--accent); transition: background .4s, color .4s;
}
.mv-icon .material-icons { font-size: 17px; }
.mv-body { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.mv-head { display: flex; justify-content: space-between; align-items: baseline; gap: 6px; }
.mv-label { font-size: 10px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: rgba(0, 0, 0, .54); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mv-updated { font-size: 10px; color: #f44336; white-space: nowrap; }
.mv-main { display: flex; align-items: baseline; gap: 4px; white-space: nowrap; line-height: 1.1; }
.mv-value { font-size: 20px; font-weight: 600; }
.mv-unit { font-size: 12px; font-weight: 500; color: rgba(0, 0, 0, .54); }
.mv-hint { font-size: 11px; font-weight: 500; color: var(--accent); transition: color .4s; }
.mv-bar { position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: rgba(0, 0, 0, .06); }
.mv-fill { height: 100%; width: 0; background: var(--accent); transition: width .6s ease, background .6s ease; }
.mv-spark { position: absolute; right: 14px; top: 8px; bottom: 9px; width: 40%; pointer-events: none; overflow: visible; }
.mv-hint { margin-left: 6px; }
.mv-gear { position: absolute; right: 10px; top: 50%; transform: translateY(-50%); width: 40px; height: 40px; border: 0; border-radius: 50%; background: transparent; color: rgba(0, 0, 0, .45); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: background .15s, color .15s; }
.mv-gear:hover { background: color-mix(in srgb, var(--accent) 14%, #fff); color: var(--accent); }
.mv-gear .material-icons { font-size: 28px; }
.mv-root { -webkit-user-select: none; user-select: none; }
.mv-root input { -webkit-user-select: text; user-select: text; }

descriptor.controllerScript:
var timer, lastTs, el, gradId;

function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"]/g, function(c) {
        return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c];
    });
}

var GREEN = '#4caf50', ORANGE = '#ff9800', RED = '#f44336', BLUE = '#2196f3', GREY = '#90a4ae';

function state(kind, v) {
    if (kind === 'grid') {
        return v > 0 ? { color: RED, hint: 'Exporting to grid' } :
               v < 0 ? { color: GREEN, hint: 'Charging' } : { color: GREY, hint: 'Idle' };
    }
    if (kind === 'soc') {
        return { color: v <= 20 ? RED : v <= 40 ? ORANGE : GREEN, hint: v <= 10 ? 'Very low' : v <= 20 ? 'Low' : v >= 99 ? 'Full' : '' };
    }
    if (kind === 'temp') {
        return v < 5 ? { color: BLUE, hint: 'Cold' } : v < 40 ? { color: GREEN, hint: 'Normal' } :
               v < 50 ? { color: ORANGE, hint: 'Warm' } : { color: RED, hint: 'Hot' };
    }
    return null;
}

function age() {
    if (!lastTs) { return; }
    var sec = Math.round((Date.now() - lastTs) / 1000);
    var node = el.querySelector('.mv-updated');
    node.textContent = sec > 180 ? 'no data for ' + Math.round(sec / 60) + ' min' : '';
}

self.onInit = function() {
    var s = self.ctx.settings || {};
    gradId = 'mvg' + Math.random().toString(36).slice(2);
    el = self.ctx.$container[0].querySelector('.mv-root');
    el.innerHTML =
        '<div class="mv-card" style="--accent:' + esc(s.color || '#2196f3') + '">' +
        '<div class="mv-icon"><span class="material-icons">' + esc(s.icon || 'bolt') + '</span></div>' +
        '<div class="mv-body">' +
        '<div class="mv-head"><span class="mv-label">' + esc(s.label) + '</span><span class="mv-updated"></span></div>' +
        '<div class="mv-main"><span class="mv-value">–</span><span class="mv-unit">' + esc(s.units) + '</span>' +
        '<span class="mv-hint"></span></div></div>' +
        '<svg class="mv-spark" viewBox="0 0 100 30" preserveAspectRatio="none"></svg>' +
        (s.kind === 'soc' ? '<div class="mv-bar"><div class="mv-fill"></div></div>' : '') +
        (s.gear ? '<button type="button" class="mv-gear" title="Settings"><span class="material-icons">settings</span></button>' : '') +
        '</div>';
    timer = setInterval(age, 15000);

    var gearButton = el.querySelector('.mv-gear');
    if (gearButton) {
        gearButton.addEventListener('click', function(event) {
            event.stopPropagation();
            var gears = self.ctx.actionsApi.getActionDescriptors('gearClick');
            if (!gears || !gears.length) { return; }
            var ds = self.ctx.datasources && self.ctx.datasources[0];
            var entityId = ds && ds.entityId ? { entityType: ds.entityType, id: ds.entityId } : null;
            self.ctx.actionsApi.handleWidgetAction(event, gears[0], entityId, ds && ds.entityName, null, ds && ds.entityLabel);
        });
    }

    var descriptors = self.ctx.actionsApi.getActionDescriptors('cardClick');
    if (descriptors && descriptors.length) {
        var card = el.querySelector('.mv-card');
        card.classList.add('clickable');
        card.title = descriptors[0].name || '';
        card.addEventListener('click', function(event) {
            var ds = self.ctx.datasources && self.ctx.datasources[0];
            var entityId = ds && ds.entityId ? { entityType: ds.entityType, id: ds.entityId } : null;
            self.ctx.actionsApi.handleWidgetAction(event, descriptors[0], entityId, ds && ds.entityName, null, ds && ds.entityLabel);
        });
    }
};

function spark(points) {
    var svg = el.querySelector('.mv-spark');
    var vals = [];
    var n = Math.min(points.length, 80);
    var size = points.length / n;
    for (var i = 0; i < n; i++) {
        var chunk = points.slice(Math.floor(i * size), Math.floor((i + 1) * size) || undefined);
        var sum = 0;
        chunk.forEach(function(p) { sum += p; });
        vals.push(sum / chunk.length);
    }
    if (vals.length < 2) { svg.innerHTML = ''; return; }
    var lo = Math.min.apply(null, vals), hi = Math.max.apply(null, vals);
    var span = hi - lo || 1;
    var xy = vals.map(function(v, i) {
        var y = hi === lo ? 15 : 27 - ((v - lo) / span) * 24;
        return (i / (vals.length - 1) * 100).toFixed(2) + ',' + y.toFixed(2);
    });
    svg.innerHTML =
        '<defs><linearGradient id="' + gradId + '" x1="0" y1="0" x2="0" y2="1">' +
        '<stop offset="0" stop-color="var(--accent)" stop-opacity=".28"/>' +
        '<stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>' +
        '<polygon points="0,30 ' + xy.join(' ') + ' 100,30" fill="url(#' + gradId + ')"/>' +
        '<polyline points="' + xy.join(' ') + '" fill="none" stroke="var(--accent)" stroke-width="1.6" ' +
        'vector-effect="non-scaling-stroke" stroke-linejoin="round" stroke-linecap="round"/>';
}

self.onDataUpdated = function() {
    var s = self.ctx.settings || {};
    var d = self.ctx.data && self.ctx.data[0] && self.ctx.data[0].data;
    if (!d || !d.length) { return; }
    var last = d[d.length - 1];
    var raw = last[1];
    var num = Number(raw);
    var isNum = raw !== '' && raw !== null && !isNaN(num);
    var card = el.querySelector('.mv-card');
    var shown = raw;
    if (isNum) {
        var v = s.divisor ? num / s.divisor : num;
        shown = s.decimals != null ? v.toFixed(s.decimals) : String(v);
        num = v;
        var st = state(s.kind, v);
        if (st) {
            el.querySelector('.mv-hint').textContent = st.hint;
            card.style.setProperty('--accent', st.color);
        }
    }
    el.querySelector('.mv-value').textContent = shown;
    if (s.kind === 'soc' && isNum) {
        var fill = el.querySelector('.mv-fill');
        fill.style.width = Math.max(0, Math.min(100, num)) + '%';
    }
    if (isNum) {
        var series = [];
        d.forEach(function(p) {
            var x = Number(p[1]);
            if (!isNaN(x)) { series.push(s.divisor ? x / s.divisor : x); }
        });
        spark(series);
    }
    lastTs = last[0];
    age();
};

self.onDestroy = function() {
    clearInterval(timer);
};

self.typeParameters = function() {
    return { maxDatasources: 1, maxDataKeys: 1, dataKeysOptional: false };
};

self.actionSources = function() {
    return { cardClick: { name: 'Card click', multiple: true }, gearClick: { name: 'Gear button click', multiple: true } };
};
